import { writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { setTimeout } from "node:timers/promises";
let body = "";
for await (const chunk of process.stdin) body += chunk;
const message = JSON.parse(body);
if (!Number.isSafeInteger(message.id)) throw new Error("invalid fixture message");
const directory = process.argv[2];
writeFileSync(join(directory, `${message.id}.started`), "started");
for (let i = 0; i < 200 && !existsSync(join(directory, "allow")); i++) await setTimeout(25);
if (!existsSync(join(directory, "allow"))) process.exit(1);
writeFileSync(join(directory, `${message.id}.handled`), "handled");
